def count_alternating_building_selections(s):
    total_zeros=s.count('0');total_ones=len(s)-total_zeros
    left_zeros=left_ones=answer=0
    for char in s:
        if char=='0':
            answer+=left_ones*(total_ones-left_ones)
            left_zeros+=1
        else:
            answer+=left_zeros*(total_zeros-left_zeros)
            left_ones+=1
    return answer

